mapper.select:
select custcd, custnm, bossnm as usernm, telno as company_tel, telno as hpno, address, email, custgbn, status
from haba020t_tbl
where cmpycd = #{cmpycd} and custcd = #{custcd}

mapper.update:
update call_mst_tbl
set TRB_MENT = IFNULL(#{trb_ment, jdbcType=VARCHAR}, TRB_MENT),
    ANS_MENT = IFNULL(#{ans_ment, jdbcType=VARCHAR}, ANS_MENT),
    AI_SUMMARY = #{ai_summary, jdbcType=VARCHAR},
    UPDTIME = NOW(),
    UPDEMP = #{updemp, jdbcType=VARCHAR}
WHERE CMPYCD = #{cmpycd}
AND SVCNO = #{svcno}

mapper.select:
select a.start_time, c.custnm, a.call_telno as hpno, a.call_usernm, a.call_email, a.svcno, a.ai_summary, a.trb_ment, a.ans_ment, a.esc_memo, u.usernm as consultnm, a.consultid, a.rec_file, a.cmpycd FROM CALL_MST_TBL A left join haba020t_tbl c on a.cmpycd = c.cmpycd and a.custcd = c.custcd left join haba920t_tbl u on a.cmpycd = u.cmpycd and a.consultid = u.userid WHERE A.CMPYCD = #{cmpycd, jdbcType=VARCHAR} AND A.SVCYMD BETWEEN #{fromdt, jdbcType=VARCHAR} AND #{todt, jdbcType=VARCHAR}
AND C.CUSTNM LIKE CONCAT('%', #{custnm, jdbcType=VARCHAR}, '%')
order by a.start_time desc

SELECT a.start_time, a.src_no, IFNULL(b.custnm, a.keyword) as custnm, a.callback_no, a.rec_file, a.callback_agent_id, a.result_cd, a.callback_rec_file, a.call_memo, a.interaction_id, a.status as callback_status FROM total_interaction_log a LEFT JOIN haba020t_tbl b ON a.cmpycd = b.cmpycd AND a.src_no = b.telno WHERE a.cmpycd = #{cmpycd} AND a.callback_yn = 'y'
AND a.start_time >= #{fromdt}
AND a.start_time <= #{todt}
ORDER BY a.start_time DESC
